insert into public.lesson_segment_slides (segment_id, position, title, body, image_storage_path, source_label, source_page, alt_text) select seg.id, 1, $b$Comprobación de Instalaciones Eléctricas, Hidráulicas y Neumáticas$b$, $b$Explicación detallada
Señales de defecto
En electricidad se observan armarios abiertos, conductores dañados, olor, calentamiento, humedad, protecciones disparadas o conexiones improvisadas. En hidráulica se buscan manchas, mangueras rozadas, abultamiento, soportes defectuosos y movimientos irregulares. En neumática se comprueban latiguillos, racores, purgas y sonido de fuga. Nunca se localiza una fuga con la mano: un chorro fino puede penetrar la piel.
Los indicadores deben guardar coherencia con el estado del proceso. Presión nula con actuador cargado o lectura fija durante cambios puede indicar fallo del instrumento. No se da por segura una línea solo porque el manómetro marque cero; se aísla, descarga y verifica por el método previsto.

Aislamiento coordinado
El esquema y la identificación de seccionadores, válvulas y acumuladores son esenciales. Se corta la fuente, se impide la reconexión, se descarga la energía residual y se asegura cualquier elemento sostenido. En electricidad se aplican las reglas del procedimiento y la competencia del trabajador; en proximidad a partes en tensión se respetan zonas y medidas del RD 614/2001. El bloqueo de un motor no controla por sí solo presión, gravedad o alimentación externa.$b$, 'f5a7da9c-a3f2-4163-bb65-90395827f146/slides/establecimientos-20h-2026/2.5/slide-01.png', 'Establecimientos de beneficio · presentación 20 h Inmíner Campus', 'Diapositiva 1', 'Diapositiva 1 de la unidad 2.5' from public.lesson_audio_segments seg join public.lessons l on l.id = seg.lesson_id join public.course_modules m on m.id = l.module_id where m.course_version_id = 'f5a7da9c-a3f2-4163-bb65-90395827f146' and m.position = 2 and seg.position = 5 and not exists (select 1 from public.lesson_segment_slides x where x.segment_id = seg.id and x.position = 1);
update public.lesson_segment_slides s set body = $b$Explicación detallada
Señales de defecto
En electricidad se observan armarios abiertos, conductores dañados, olor, calentamiento, humedad, protecciones disparadas o conexiones improvisadas. En hidráulica se buscan manchas, mangueras rozadas, abultamiento, soportes defectuosos y movimientos irregulares. En neumática se comprueban latiguillos, racores, purgas y sonido de fuga. Nunca se localiza una fuga con la mano: un chorro fino puede penetrar la piel.
Los indicadores deben guardar coherencia con el estado del proceso. Presión nula con actuador cargado o lectura fija durante cambios puede indicar fallo del instrumento. No se da por segura una línea solo porque el manómetro marque cero; se aísla, descarga y verifica por el método previsto.

Aislamiento coordinado
El esquema y la identificación de seccionadores, válvulas y acumuladores son esenciales. Se corta la fuente, se impide la reconexión, se descarga la energía residual y se asegura cualquier elemento sostenido. En electricidad se aplican las reglas del procedimiento y la competencia del trabajador; en proximidad a partes en tensión se respetan zonas y medidas del RD 614/2001. El bloqueo de un motor no controla por sí solo presión, gravedad o alimentación externa.$b$, title = $b$Comprobación de Instalaciones Eléctricas, Hidráulicas y Neumáticas$b$, image_storage_path = 'f5a7da9c-a3f2-4163-bb65-90395827f146/slides/establecimientos-20h-2026/2.5/slide-01.png', image_external_url = null, updated_at = now() from public.lesson_audio_segments seg join public.lessons l on l.id = seg.lesson_id join public.course_modules m on m.id = l.module_id where s.segment_id = seg.id and m.course_version_id = 'f5a7da9c-a3f2-4163-bb65-90395827f146' and m.position = 2 and seg.position = 5 and s.position = 1;
insert into public.lesson_segment_slides (segment_id, position, title, body, image_storage_path, source_label, source_page, alt_text) select seg.id, 2, $b$Aplicación segura · Comprobación de Instalaciones Eléctricas, Hidráulicas y Neumáticas$b$, $b$Aplicación práctica
Intervención y restitución
Una manguera se sustituye por componente compatible y se enruta sin torsión, roce o radio inadecuado. Los conectores no se fuerzan ni adaptan con piezas improvisadas. En cuadros se conserva grado de protección, puesta a tierra e identificación. Después de una reparación, la presurización o energización es gradual, con personas fuera de la zona de posible fuga o movimiento.
El operador comprueba estanqueidad y función desde posición segura. Una protección que dispara de nuevo no se rearma repetidamente; se investiga la causa. Toda modificación de esquema, componente o ajuste se documenta. Las instalaciones seguras dependen de que la configuración real coincida con planos, etiquetas y procedimientos.

Profundización: verificación de cero energía
La identificación comienza en el esquema y se confirma físicamente. Un equipo puede recibir electricidad por más de un circuito, presión desde un acumulador o movimiento por una carga elevada. Por eso se separa cada fuente, se bloquea el órgano de corte, se descarga y se intenta comprobar el estado mediante el método previsto. En electricidad, la verificación de ausencia de tensión corresponde a personal competente con equipo adecuado; pulsar el mando no sustituye esa comprobación.
Las fugas hidráulicas y neumáticas se localizan sin exponer piel u ojos y nunca se aprietan bajo presión. Un actuador se apoya o bloquea mecánicamente antes de trabajar debajo. Al restituir, se revisan herramientas, conexiones, protecciones y posición de válvulas. La energía entra gradualmente y nadie permanece frente a un racor. Si una protección vuelve a disparar, se conserva el equipo fuera de servicio: los rearmes sucesivos pueden transformar un defecto detectable en una rotura.

Idea clave
Cero en un indicador no demuestra cero energía: hay que aislar, descargar y verificar cada fuente que pueda producir movimiento, presión o contacto.$b$, 'f5a7da9c-a3f2-4163-bb65-90395827f146/slides/establecimientos-20h-2026/2.5/slide-02.png', 'Establecimientos de beneficio · presentación 20 h Inmíner Campus', 'Diapositiva 2', 'Diapositiva 2 de la unidad 2.5' from public.lesson_audio_segments seg join public.lessons l on l.id = seg.lesson_id join public.course_modules m on m.id = l.module_id where m.course_version_id = 'f5a7da9c-a3f2-4163-bb65-90395827f146' and m.position = 2 and seg.position = 5 and not exists (select 1 from public.lesson_segment_slides x where x.segment_id = seg.id and x.position = 2);
