insert into public.lesson_segment_slides (segment_id, position, title, body, image_storage_path, source_label, source_page, alt_text) select seg.id, 1, $b$Cintas, Alimentadores, Tolvas y Transferencias$b$, $b$Explicación detallada
Puntos peligrosos
Tambores motriz y de retorno, rodillos, tensores, rascadores, acoplamientos y zonas donde la banda cambia de dirección pueden arrastrar una extremidad o una prenda. Las transferencias reciben material con energía y pueden proyectar fragmentos. Un desalineamiento lleva la banda hacia estructura y genera derrame o daño. La inspección se realiza desde fuera de resguardos, sin tocar la banda ni introducir útiles.
Las pasarelas deben permitir tránsito sin invadir el gálibo. El material derramado no se acumula hasta cubrir cables de parada o estrechar una evacuación. La limpieza automática, rascadores y faldones se mantienen para reducir intervención manual, pero también se tratan como órganos de la máquina.

Mandos y comunicación
Antes de arrancar se emite aviso y se confirma la zona. Los cables y pulsadores de parada se distribuyen y prueban, pero no sustituyen el bloqueo. Los modos local y remoto deben estar definidos para que una orden no sorprenda a otra persona. Durante mantenimiento se controla el seccionador y cualquier automatismo de secuencia. La radio ayuda, pero la seguridad no puede depender solo de que alguien oiga un mensaje.$b$, 'f5a7da9c-a3f2-4163-bb65-90395827f146/slides/establecimientos-20h-2026/3.3/slide-01.png', 'Establecimientos de beneficio · presentación 20 h Inmíner Campus', 'Diapositiva 1', 'Diapositiva 1 de la unidad 3.3' from public.lesson_audio_segments seg join public.lessons l on l.id = seg.lesson_id join public.course_modules m on m.id = l.module_id where m.course_version_id = 'f5a7da9c-a3f2-4163-bb65-90395827f146' and m.position = 3 and seg.position = 3 and not exists (select 1 from public.lesson_segment_slides x where x.segment_id = seg.id and x.position = 1);
update public.lesson_segment_slides s set body = $b$Explicación detallada
Puntos peligrosos
Tambores motriz y de retorno, rodillos, tensores, rascadores, acoplamientos y zonas donde la banda cambia de dirección pueden arrastrar una extremidad o una prenda. Las transferencias reciben material con energía y pueden proyectar fragmentos. Un desalineamiento lleva la banda hacia estructura y genera derrame o daño. La inspección se realiza desde fuera de resguardos, sin tocar la banda ni introducir útiles.
