insert into public.lesson_segment_slides (segment_id, position, title, body, image_storage_path, source_label, source_page, alt_text) select seg.id, 1, $b$Equipos e Instrumental de Laboratorio$b$, $b$Explicación detallada
Recepción y preparación de muestras
La muestra se identifica desde su llegada y se conserva en recipiente adecuado. Secado, cuarteo, trituración o molienda se realizan con equipos protegidos y extracción. No se abre un molino de laboratorio hasta que haya parado y quedado aislado. Las piezas calientes se señalizan y se manipulan con útiles. La limpieza entre muestras evita contaminación y también exposición al polvo.
El tamaño reducido favorece sostener manualmente, pero no debe acercarse la mano al órgano. Se usan empujadores y puntos de alimentación. Los recipientes de vidrio se inspeccionan; presión o vacío requieren material diseñado y pantalla cuando proceda.

Reactivos y extracción
Antes de usar un producto se consulta etiqueta y ficha: peligros, incompatibilidades, ventilación, EPI, derrames y residuos. Nunca se trasvasa a envase de bebida ni se deja sin nombre. La campana se utiliza con la pantalla a la altura indicada y sin bloquear el flujo. Los productos incompatibles se separan y las cantidades se limitan a las necesarias.$b$, 'f5a7da9c-a3f2-4163-bb65-90395827f146/slides/establecimientos-20h-2026/3.8/slide-01.png', 'Establecimientos de beneficio · presentación 20 h Inmíner Campus', 'Diapositiva 1', 'Diapositiva 1 de la unidad 3.8' from public.lesson_audio_segments seg join public.lessons l on l.id = seg.lesson_id join public.course_modules m on m.id = l.module_id where m.course_version_id = 'f5a7da9c-a3f2-4163-bb65-90395827f146' and m.position = 3 and seg.position = 8 and not exists (select 1 from public.lesson_segment_slides x where x.segment_id = seg.id and x.position = 1);
update public.lesson_segment_slides s set body = $b$Explicación detallada
Recepción y preparación de muestras
La muestra se identifica desde su llegada y se conserva en recipiente adecuado. Secado, cuarteo, trituración o molienda se realizan con equipos protegidos y extracción. No se abre un molino de laboratorio hasta que haya parado y quedado aislado. Las piezas calientes se señalizan y se manipulan con útiles. La limpieza entre muestras evita contaminación y también exposición al polvo.
El tamaño reducido favorece sostener manualmente, pero no debe acercarse la mano al órgano. Se usan empujadores y puntos de alimentación. Los recipientes de vidrio se inspeccionan; presión o vacío requieren material diseñado y pantalla cuando proceda.

Reactivos y extracción
Antes de usar un producto se consulta etiqueta y ficha: peligros, incompatibilidades, ventilación, EPI, derrames y residuos. Nunca se trasvasa a envase de bebida ni se deja sin nombre. La campana se utiliza con la pantalla a la altura indicada y sin bloquear el flujo. Los productos incompatibles se separan y las cantidades se limitan a las necesarias.$b$, title = $b$Equipos e Instrumental de Laboratorio$b$, image_storage_path = 'f5a7da9c-a3f2-4163-bb65-90395827f146/slides/establecimientos-20h-2026/3.8/slide-01.png', image_external_url = null, updated_at = now() from public.lesson_audio_segments seg join public.lessons l on l.id = seg.lesson_id join public.course_modules m on m.id = l.module_id where s.segment_id = seg.id and m.course_version_id = 'f5a7da9c-a3f2-4163-bb65-90395827f146' and m.position = 3 and seg.position = 8 and s.position = 1;
insert into public.lesson_segment_slides (segment_id, position, title, body, image_storage_path, source_label, source_page, alt_text) select seg.id, 2, $b$Aplicación segura · Equipos e Instrumental de Laboratorio$b$, $b$Aplicación práctica
Incidencias y residuos
Un derrame se controla según producto y kit disponible, delimitando el área y evitando reacciones improvisadas. En contacto se aplican ducha o lavaojos y se solicita ayuda. Los residuos se segregan, etiquetan y cierran; no se mezclan para ahorrar recipientes. Las agujas, vidrio o sólidos cortantes tienen contenedores específicos.
Los equipos se calibran y mantienen para evitar decisiones de proceso basadas en datos erróneos. Una desviación analítica se investiga junto con el estado del instrumento y la muestra. La trazabilidad —quién, cuándo, método y resultado — es parte de la seguridad, porque permite reconstruir exposiciones y evitar repetir una preparación peligrosa.

Profundización: calidad analítica y prevención
Un resultado fiable exige muestra identificada, método, calibración y registro. La contaminación cruzada no solo afecta calidad: puede provocar reacciones al mezclar residuos o reactivos. Los equipos de preparación se limpian con extracción y aislamiento. Hornos, estufas y placas conservan calor y las muestras se marcan hasta enfriarse. Los recipientes sometidos a vacío o presión deben estar diseñados e inspeccionados.
La campana se comprueba antes de manipular productos volátiles y no se utiliza como almacén permanente. La ficha determina guante, protección ocular y respuesta a derrame. Los productos incompatibles se separan. Si una muestra o envase pierde etiqueta, se inmoviliza y se identifica por procedimiento; nunca se huele o prueba. El historial del instrumento y del reactivo permite investigar resultados anómalos sin repetir innecesariamente una preparación peligrosa.

Idea clave
En laboratorio, cada muestra, reactivo y residuo debe conservar identificación; un recipiente sin trazabilidad no se manipula hasta aclarar su contenido.$b$, 'f5a7da9c-a3f2-4163-bb65-90395827f146/slides/establecimientos-20h-2026/3.8/slide-02.png', 'Establecimientos de beneficio · presentación 20 h Inmíner Campus', 'Diapositiva 2', 'Diapositiva 2 de la unidad 3.8' from public.lesson_audio_segments seg join public.lessons l on l.id = seg.lesson_id join public.course_modules m on m.id = l.module_id where m.course_version_id = 'f5a7da9c-a3f2-4163-bb65-90395827f146' and m.position = 3 and seg.position = 8 and not exists (select 1 from public.lesson_segment_slides x where x.segment_id = seg.id and x.position = 2);
update public.lesson_segment_slides s set body = $b$Aplicación práctica
