do $val$
declare
  v5 constant uuid := '4945d77b-d931-4054-a534-8a7466ce6a0b';
  v20 constant uuid := 'f5a7da9c-a3f2-4163-bb65-90395827f146';
  fallos integer;
begin
  select count(*)
    into fallos
    from (values (v5), (v20)) as v(id)
   where (
     select count(*)
       from public.lesson_segment_slides s
       join public.lesson_audio_segments seg on seg.id = s.segment_id
       join public.lessons l on l.id = seg.lesson_id
       join public.course_modules m on m.id = l.module_id
      where m.course_version_id = v.id
   ) <> 100;
  if fallos > 0 then
    raise exception '% modalidades de establecimientos de beneficio no tienen 100 diapositivas', fallos;
  end if;

  select count(*)
    into fallos
    from public.lesson_segment_slides s
    join public.lesson_audio_segments seg on seg.id = s.segment_id
    join public.lessons l on l.id = seg.lesson_id
    join public.course_modules m on m.id = l.module_id
   where m.course_version_id in (v5, v20)
     and (
       length(s.body) < 900
       or (s.position = 1 and s.body not like 'Explicación detallada%')
       or (s.position = 2 and s.body not like 'Aplicación práctica%')
       or (s.position = 2 and s.body not like '%Idea clave%')
     );
  if fallos > 0 then
    raise exception '% diapositivas de establecimientos de beneficio no llevan la explicación del manual', fallos;
  end if;

  -- Cada modalidad debe apuntar a su propia carpeta: la política de lectura del
  -- bucket exige que la primera carpeta sea la versión matriculada.
  select count(*)
    into fallos
    from public.lesson_segment_slides s
    join public.lesson_audio_segments seg on seg.id = s.segment_id
    join public.lessons l on l.id = seg.lesson_id
    join public.course_modules m on m.id = l.module_id
   where m.course_version_id in (v5, v20)
     and (
       s.image_storage_path is null
       or s.image_storage_path not like m.course_version_id::text || '/%'
     );
  if fallos > 0 then
    raise exception '% diapositivas apuntan a la carpeta de otra versión', fallos;
  end if;

  -- Las transcripciones de ambas modalidades no pueden coincidir: el manual
  -- registra una locución de formación inicial y otra abreviada de reciclaje.
  select count(*)
    into fallos
    from public.lesson_audio_segments a
    join public.lessons la on la.id = a.lesson_id
    join public.course_modules ma on ma.id = la.module_id
    join public.course_modules mb on mb.course_version_id = v20 and mb.position = ma.position
    join public.lessons lb on lb.module_id = mb.id
    join public.lesson_audio_segments b on b.lesson_id = lb.id and b.position = a.position
   where ma.course_version_id = v5
     and a.narration_text = b.narration_text;
  if fallos > 0 then
    raise exception '% unidades comparten transcripción entre las dos modalidades', fallos;
  end if;
end;
$val$;

commit;
